/// The `m2` and room count inputs, one `Vec` per sample.
pub fn gemini_created_inputs_data_set() -> Vec<Vec<f64>> {
    INPUTS.iter().map(|sample| sample.to_vec()).collect()
}

/// The rental price expected for each sample of [`gemini_created_inputs_data_set`].
pub fn gemini_created_outputs() -> Vec<f64> {
    OUTPUTS.to_vec()
}
